    type: "energy",
    parent: "IL-D",
    coords: [34.7350, 31.0250],
    name: { de: "Sonnenkraftwerk Ashalim", hu: "Ashalim Naperőmű", ro: "Centrala Solară Ashalim", en: "Ashalim Power Station"},
    image: "/poi-images/il-ashalim-economic-v2.webp",
    description: { de: "Ein innovatives Solarkraftwerk in der Negev-Wüste, das einen der höchsten Solartürme der Welt besitzt und erneuerbare Energie liefert.", hu: "Innovatív naperőmű a Negev-sivatagban, amely a világ egyik legmagasabb naptornyával rendelkezik, és megújuló energiát szolgáltat.", ro: "O centrală solară inovatoare în deșertul Negev, cu unul dintre cele mai înalte turnuri solare din lume, furnizând energie regenerabilă.", en: "An innovative solar power plant in the Negev Desert, featuring one of the tallest solar towers in the world and providing renewable energy." },
    facts: {
      de: ["Turmhöhe von über 240 Metern.", "Nutzt Tausende von Spiegeln.", "Wichtig für grüne Energie in Israel."],
      hu: ["A torony magassága több mint 240 méter.", "Több ezer tükröt használ.", "Fontos a zöld energia szempontjából Izraelben."],
      ro: ["Înălțimea turnului este de peste 240 de metri.", "Folosește mii de oglinzi.", "Importantă pentru energia verde în Israel."],
      en: ["Tower height of over 240 meters.", "Uses thousands of mirrors.", "Important for green energy in Israel."]
    }, image: "/poi-images/il-ashalim-economic-v2.webp",
    descriptionAdvanced: {
      de: "Das Ashalim-Kraftwerk ist eines der weltweit ambitioniertesten Projekte im Bereich der erneuerbaren Energien und befindet sich in der Negev-Wüste in Israel. Es handelt sich um einen kombinierten Komplex aus Solarthermie- und Photovoltaikanlagen, der darauf ausgelegt ist, die intensive Sonneneinstrahlung der Wüste effizient zu nutzen. Das markanteste Merkmal der Anlage ist der 250 Meter hohe Solarturm, der von über 50.000 computergesteuerten Spiegeln (Heliostaten) umgeben ist, die das Sonnenlicht auf die Spitze des Turms konzentrieren. Dort wird Dampf erzeugt, der eine Turbine zur Stromerzeugung antreibt. Neben der Solarthermie umfasst der Komplex auch großflächige Photovoltaik-Felder, die direkt Strom aus Sonnenlicht gewinnen. Ashalim ist ein zentraler Baustein der israelischen Strategie, den Anteil erneuerbarer Energien am nationalen Energiemix signifikant zu erhöhen und die Abhängigkeit von fossilen Brennstoffen zu verringern. Die Anlage leistet einen wichtigen Beitrag zur Reduzierung von Treibhausgasemissionen und demonstriert die technologische Innovationskraft Israels im Bereich der sauberen Energie. Die Lage in der Wüste bietet ideale Bedingungen für die großflächige Gewinnung von Solarenergie.",
      hu: "Az ashalimi erőmű a világ egyik legambiciózusabb megújuló energia projektje, amely Izraelben, a Negev-sivatag szívében található. Ez egy komplex létesítmény, amely napenergia-toronyból, vályús napkollektorokból és fotovoltaikus panelekből áll, kihasználva a sivatag intenzív napsütését. A projekt leglátványosabb eleme a 250 méter magas szolártorony, amelyet több mint 50 000 számítógép-vezérelt tükör (heliosztát) vesz körül. Ezek a tükrök a torony tetejére fókuszálják a fényt, ahol a keletkező hő gőzt fejleszt a turbinák meghajtásához. Az erőmű nemcsak technológiai bravúr, hanem Izrael elkötelezettségének jelképe is a tiszta energia és a fenntartható fejlődés mellett. Ashalim kulcsfontosságú az ország azon törekvésében, hogy csökkentse a fosszilis tüzelőanyagoktól való függőségét és minimalizálja a szén-dioxid-kibocsátást. A létesítmény évi több százezer tonna károsanyag kibocsátását váltja ki, miközben több tízezer háztartást lát el elektromos árammal. A sivatagi elhelyezkedés ideális feltételeket biztosít a nagyüzemi napenergia-termeléshez, bemutatva a jövő energetikai megoldásait.",
      ro: "Centrala electrică Ashalim este unul dintre cele mai ambițioase proiecte de energie regenerabilă din lume, situată în deșertul Negev din Israel. Complexul integrează tehnologii variate, inclusiv energie solară termică concentrată (CSP) și panouri fotovoltaice, profitând de radiația solară intensă a regiunii. Elementul central al instalației este turnul solar cu o înălțime de 250 de metri, unul dintre cele mai înalte de acest tip de pe glob. Acesta este înconjurat de un câmp vast de peste 50.000 de oglinzi (heliostate) care urmăresc soarele și concentrează razele în vârful turnului pentru a genera abur de înaltă presiune. Ashalim joacă un rol esențial în strategia Israelului de a atinge obiectivele climatice și de a reduce dependența de importurile de combustibili fosili. Pe lângă impactul său energetic, proiectul este un model de inovație tehnologică și inginerie sustenabilă în condiții climatice extreme. Capacitatea sa permite alimentarea a zeci de mii de locuințe cu energie curată, contribuind masiv la reducerea amprentei de carbon a țării. Centrala transformă deșertul într-o resursă strategică pentru viitorul verde al regiunii.",
      en: "The Ashalim Power Station is one of the world's most ambitious renewable energy projects, located in the Negev Desert of Israel. This multi-technology complex combines concentrated solar power (CSP) with massive photovoltaic arrays to harness the desert's intense solar radiation. Its most striking feature is the 250-meter-tall solar power tower, one of the highest structures of its kind globally, surrounded by over 50,000 computer-controlled mirrors known as heliostats. These mirrors focus sunlight onto a boiler at the tower's summit to generate high-pressure steam for electricity production. Ashalim is a cornerstone of Israel's national strategy to diversify its energy portfolio and significantly increase the share of renewables in the power grid. By producing clean energy for tens of thousands of homes, the facility drastically reduces annual carbon dioxide emissions. The project exemplifies cutting-edge engineering and Israel's commitment to sustainable development in arid environments. Its presence has transformed the landscape of the Negev into a hub for global solar innovation and energy independence.",
    },
    factsAdvanced: {
      de: ["Beherbergt einen der weltweit höchsten Solartürme mit 250 Metern Höhe.", "Über 50.000 computergesteuerte Heliostaten reflektieren das Sonnenlicht.", "Befindet sich in der zentralen Negev-Wüste bei Ashalim.", "Kombiniert drei verschiedene Solartechnologien an einem Standort.", "Versorgt schätzungsweise 120.000 Haushalte mit sauberem Strom.", "Reduziert den jährlichen CO2-Ausstoß um ca. 110.000 Tonnen."],
      hu: ["A szolártorony 250 méteres magasságával a világ egyik legmagasabbja.", "Több mint 50 000 heliosztát (tükör) követi a nap mozgását a területen.", "A Negev-sivatagban található, ahol a napsütéses órák száma rendkívül magas.", "A komplexum összteljesítménye eléri a 121 megawattot.", "Képes hőtárolásra is, így a napszállta után is tud áramot termelni.", "Izrael legnagyobb megújuló energiát előállító létesítménye."],
      ro: ["Turnul solar central are o înălțime record de 250 de metri.", "Sistemul folosește 50.600 de oglinzi controlate prin software avansat.", "Situată în deșertul Negev, o zonă cu potențial solar maxim.", "Complexul Ashalim furnizează aproximativ 1% din electricitatea Israelului.", "Tehnologia CSP permite generarea de energie chiar și în perioadele fără soare.", "A fost rezultatul unei colaborări public-privat internaționale majore."],
      en: ["Features a solar power tower standing at a staggering height of 250 meters.", "Surrounded by a field of 50,600 heliostats covering several square kilometers.", "Located in the Negev Desert, optimizing high annual solar irradiance.", "Supplies clean electricity to roughly 120,000 households across Israel.", "Utilizes molten salt storage to continue generating power after sunset.", "Significantly lowers national carbon emissions by about 110,000 tons per year."],
    },
